function p = iso8608Profile(roadClass, L, dx, options)
%ISO8608PROFILE Generate a 1D road profile from the ISO 8608 PSD.
%   P = ISO8608PROFILE(CLASS, L, DX) returns a struct P with fields x, z,
%   dx, containing a synthetic road profile of length L (in metres) sampled
%   at spatial resolution DX (in metres), for the given roughness CLASS
%   ('A' to 'H').
%
%   P = ISO8608PROFILE(..., Seed=S) uses the random seed S for
%   deterministic generation. Two calls with the same seed produce
%   identical profiles.
%
%   The profile is generated by IFFT of a one-sided PSD with random phases,
%   following the ISO 8608 model G_d(n) = G0 * (n/n0)^-2. The resulting
%   profile is mean-zero.
%
%   See also roadprofile.iso8608PSD.

arguments
    roadClass {mustBeTextScalar}
    L {mustBeNumeric, mustBePositive}
    dx {mustBeNumeric, mustBePositive}
    options.Seed = []
end

if ~isempty(options.Seed)
    previousState = rng;
    rng(options.Seed);
end
N = round(L / dx);
x = (0:N-1)' * dx;
dn = 1 / L;
if mod(N,2) == 0
    n_pos = (1:(N/2 - 1))' * dn;
    idx_pos = (2:N/2)';
else
    n_pos = (1:floor(N/2))' * dn;
    idx_pos = (2:floor(N/2)+1)';
end
G_pos = roadprofile.iso8608PSD(roadClass, n_pos);
amp = sqrt(G_pos * dn);
phi = 2 * pi * rand(size(amp));
X = zeros(N, 1);
X(idx_pos) = amp .* exp(1i * phi);
X(N - idx_pos + 2) = conj(flipud(X(idx_pos)));
z = real(ifft(X)) * N;
z = z - mean(z);
if ~isempty(options.Seed)
    rng(previousState);
end
p.x = x;
p.z = z;
p.dx = dx;
end